<main id="main" class="content-page account-page"><div class="page-heading"><p class="eyebrow">VOTRE ESPACE TASSURA</p><h1><?=user()?'Bonjour, '.e(user()['name']).'.':'Retrouvons-nous.'?></h1></div><?php if(user()):?><div class="account-toolbar"><p><?=e(user()['email'])?></p><?php if(user()['role']==='admin'):?><a class="button" href="<?=e(url('admin/index.php'))?>">Administration</a><?php endif;?><form method="post" action="<?=e(url('actions/auth.php'))?>"><?=csrf_input()?><button class="button-outline" name="operation" value="logout">Se déconnecter</button></form></div><h2>Vos commandes</h2><?php $s=db()->prepare('SELECT reference,created_at,total_millimes,status,access_token FROM orders WHERE user_id=? ORDER BY id DESC LIMIT 50');$s->execute([user()['id']]);$orders=$s->fetchAll();if(!$orders):?><p>Votre prochaine silhouette vous attend dans la collection.</p><?php else:?><div class="table-wrap"><table class="data-table"><thead><tr><th>Référence</th><th>Date</th><th>Total</th><th>État</th><th></th></tr></thead><tbody><?php foreach($orders as $o):?><tr><td><?=e($o['reference'])?></td><td><?=e($o['created_at'])?></td><td><?=e(money((int)$o['total_millimes']))?></td><td><?=e($o['status'])?></td><td><a href="<?=e(route('order',['token'=>$o['access_token']]))?>">Consulter</a></td></tr><?php endforeach;?></tbody></table></div><?php endif;?><?php else:?><div class="auth-columns"><form method="post" action="<?=e(url('actions/auth.php'))?>" class="auth-form"><?=csrf_input()?><input type="hidden" name="operation" value="login"><h2>Se connecter</h2><label class="field">E-mail<input type="email" name="email" required autocomplete="username" maxlength="190"></label><label class="field">Mot de passe<input type="password" name="password" required autocomplete="current-password" maxlength="72"></label><button class="button">Entrer dans mon espace</button></form><form method="post" action="<?=e(url('actions/auth.php'))?>" class="auth-form"><?=csrf_input()?><input type="hidden" name="operation" value="register"><h2>Créer un compte</h2><label class="field">Nom complet<input name="name" maxlength="120" required autocomplete="name"></label><label class="field">E-mail<input type="email" name="email" maxlength="190" required autocomplete="email"></label><label class="field">Mot de passe<input type="password" name="password" minlength="12" maxlength="72" required autocomplete="new-password"><small>12 caractères minimum.</small></label><button class="button-outline">Créer mon espace</button><p class="form-note">En créant un compte, vous acceptez la <a href="<?=e(route('policy',['section'=>'privacy']))?>">politique de confidentialité</a>.</p></form></div><?php endif;?></main>